-- 3) Verificación final — conteos esperados exactos:
--    total=689, lote=237, visitar=452, linea_compartida=19, misma_marca=67,
--    telefono_revisar=2, ambas_linea_y_marca=15
select
  count(*) filter (where industry = 'Dentista') as total,
  count(*) filter (where industry = 'Dentista' and 'lote-dent-sep-2026' = any(tags)) as lote,
  count(*) filter (where industry = 'Dentista' and 'visitar' = any(tags)) as visitar,
  count(*) filter (where industry = 'Dentista' and 'linea-compartida' = any(tags)) as linea_compartida,
  count(*) filter (where industry = 'Dentista' and 'misma-marca' = any(tags)) as misma_marca,
  count(*) filter (where industry = 'Dentista' and 'telefono-revisar' = any(tags)) as telefono_revisar,
  count(*) filter (where industry = 'Dentista' and 'linea-compartida' = any(tags) and 'misma-marca' = any(tags)) as ambas_linea_y_marca,
  count(*) filter (where industry = 'Dentista' and in_reserve = false) as fuera_de_reserva_debe_ser_0
from contacts
where industry = 'Dentista';
